@auto_docstring
@dataclass
class GS1DecisionOutput(ModelOutput):
    r"""Output of GS1 structured candidate scoring.

    Args:
        loss (`torch.FloatTensor` of shape `()`, *optional*): Mean GS1 decision training loss.
        logits (`torch.FloatTensor` of shape `(total_options,)`): Candidate logits concatenated by question.
    """

    loss: torch.Tensor | None = None
    logits: torch.Tensor | None = None


class GS1DecisionHead(nn.Module):
    def __init__(self, config):
        super().__init__()
        decision = config.decision
        hidden_size = config.text_config.hidden_size
        width = decision["projection_size"]
        heads = decision["cross_attention_heads"]
        eps = decision["norm_eps"]
        self.memory_norm = nn.LayerNorm(hidden_size, eps=eps)
        self.memory_projection = nn.Linear(hidden_size, hidden_size, bias=False)
        self.question_seed = nn.Linear(hidden_size, hidden_size, bias=False)
        self.question_attention = nn.MultiheadAttention(hidden_size, heads, batch_first=True)
        self.decision_projection = nn.Linear(hidden_size, hidden_size, bias=False)
        self.question_projection = nn.Linear(hidden_size, hidden_size, bias=False)
        self.question_evidence_projection = nn.Linear(hidden_size, hidden_size, bias=False)
        self.context_norm = nn.LayerNorm(hidden_size, eps=eps)
        self.option_projection = nn.Linear(hidden_size, hidden_size, bias=False)
        self.condition_projection = nn.Linear(hidden_size, hidden_size, bias=False)
        self.option_norm = nn.LayerNorm(hidden_size, eps=eps)
        self.routing_attention = nn.ModuleList(
            nn.MultiheadAttention(hidden_size, heads, batch_first=True)
            for _ in range(decision["cross_attention_layers"])
        )
        self.routing_attention_norm = nn.ModuleList(
            nn.LayerNorm(hidden_size, eps=eps) for _ in range(decision["cross_attention_layers"])
        )
        self.routing_ffn_in = nn.ModuleList(
            nn.Linear(hidden_size, hidden_size) for _ in range(decision["cross_attention_layers"])
        )
        self.routing_ffn_out = nn.ModuleList(
            nn.Linear(hidden_size, hidden_size) for _ in range(decision["cross_attention_layers"])
        )
        self.routing_output_norm = nn.ModuleList(
            nn.LayerNorm(hidden_size, eps=eps) for _ in range(decision["cross_attention_layers"])
        )
        self.query_mlp_in = nn.Linear(hidden_size, hidden_size)
        self.query_mlp_out = nn.Linear(hidden_size, width)
        self.key_mlp_in = nn.Linear(hidden_size, hidden_size)
        self.key_mlp_out = nn.Linear(hidden_size, width)
        self.query_norm = nn.LayerNorm(width, eps=eps)
        self.key_norm = nn.LayerNorm(width, eps=eps)
        self.projection_size = width
        self.bf16_compute = config.head_compute_dtype == "bfloat16"

    def forward(self, state, question, decision, options):
        dtype = torch.bfloat16 if self.bf16_compute else self.memory_projection.weight.dtype
        with torch.autocast(device_type=state.device.type, dtype=torch.bfloat16, enabled=self.bf16_compute):
            state, question, decision, options = (value.to(dtype) for value in (state, question, decision, options))
            memory = self.memory_projection(self.memory_norm(state)).unsqueeze(0)
            query = self.question_seed(question)[None, None]
            with sdpa_kernel([SDPBackend.FLASH_ATTENTION, SDPBackend.EFFICIENT_ATTENTION]):
                evidence = self.question_attention(query, memory, memory, need_weights=False)[0][0, 0]
            context = self.context_norm(
                self.decision_projection(decision)
                + self.question_projection(question)
                + self.question_evidence_projection(evidence)
            )
            routed = self.option_norm(self.option_projection(options) + self.condition_projection(context))
            for attention, attention_norm, ffn_in, ffn_out, output_norm in zip(
                self.routing_attention,
                self.routing_attention_norm,
                self.routing_ffn_in,
                self.routing_ffn_out,
                self.routing_output_norm,
                strict=True,
            ):
                with sdpa_kernel([SDPBackend.FLASH_ATTENTION, SDPBackend.EFFICIENT_ATTENTION]):
                    evidence = attention(routed[None], memory, memory, need_weights=False)[0][0]
                updated = attention_norm(routed + evidence)
                routed = output_norm(updated + ffn_out(F.gelu(ffn_in(updated))))
            query = self.query_norm(self.query_mlp_out(F.gelu(self.query_mlp_in(context))))
            keys = self.key_norm(self.key_mlp_out(F.gelu(self.key_mlp_in(routed))))
        with torch.autocast(device_type=state.device.type, enabled=False):
            return (keys.float() @ query.float()) / math.sqrt(self.projection_size)


class FADepthRouter(nn.Module):
    def __init__(self, hidden_size, eps):
        super().__init__()
        self.query = nn.Parameter(torch.zeros(hidden_size))
        self.eps = eps

    def forward(self, carry, sources):
        values = torch.stack(sources).float()
        keys = values * torch.rsqrt(values.square().mean(-1, keepdim=True) + self.eps)
        alpha = torch.einsum("d,nbtd->nbt", self.query.float(), keys).softmax(dim=0)
        correction = torch.einsum("nbt,nbtd->btd", (alpha - 1 / len(sources)) * len(sources), values)
        return (carry.float() + correction).to(carry.dtype)


class GS1DecoderLayer(nn.Module):
    """Reuse Qwen3.5 projections and kernels with GS1's residual topology."""

    def __init__(self, source):
        super().__init__()
        self.block_type = source.block_type
        self.input_layernorm = source.input_layernorm
        self.post_attention_layernorm = source.post_attention_layernorm
        self.mlp = source.mlp
        if self.block_type == "full_attention":
            self.self_attn = source.self_attn
        else:
            self.linear_attn = source.linear_attn


class GS1TextModel(nn.Module):
    def __init__(self, config):
        super().__init__()
        text, decision = config.text_config, config.decision
        self.config = config
        self.full_layers = tuple(i for i, kind in enumerate(text.layer_types) if kind == "full_attention")
        backbone = AutoModel.from_config(text)
        self.layers = nn.ModuleList(GS1DecoderLayer(layer) for layer in backbone.layers)
        self.embed_tokens = backbone.embed_tokens
        self.norm = backbone.norm
        self.rotary_emb = backbone.rotary_emb
        self.gradient_checkpointing = False
        self._gradient_checkpointing_func = checkpoint
        receivers = decision["attnres_layers"] or self.full_layers
        self.attnres_routers = nn.ModuleDict(
            {
                str(i): FADepthRouter(text.hidden_size, decision["attnres_eps"])
                for i in receivers
                if decision["attnres"]
            }
        )

    @staticmethod
    def _run_layer(layer, carry, positional, mask, read, valid):
        if layer.block_type == "full_attention":
            mixed = layer.self_attn(layer.input_layernorm(read), position_embeddings=positional, attention_mask=mask)[
                0
            ]
        else:
            mixed = layer.linear_attn(hidden_states=layer.input_layernorm(carry), attention_mask=valid)
        hidden = carry + mixed
        ffn = layer.mlp(layer.post_attention_layernorm(hidden))
        return hidden + ffn, mixed, ffn

    def forward(self, inputs_embeds, position_ids, roles, attention_mask):
        batch, length = inputs_embeds.shape[:2]
        valid = attention_mask.bool()
        if not valid[:, -1].all() or (valid[:, :-1] & ~valid[:, 1:]).any():
            raise ValueError("GS1 requires left-padded nonempty sequences")
        keep = valid.unsqueeze(-1)
        hidden = inputs_embeds * keep
        eye = torch.eye(length, dtype=torch.bool, device=hidden.device)[None]
        selected = self.config.decision["bidirectional_layers"] or self.full_layers
        bidirectional = self.config.decision["bidirectional"]
        masks = {}
        for value in {bidirectional and i in selected for i in self.full_layers}:
            if value:
                allowed = (roles[:, :, None] >= roles[:, None, :]) & (roles[:, None, :] != 3)
                allowed |= eye
            else:
                allowed = torch.ones((batch, length, length), dtype=torch.bool, device=hidden.device).tril_()
            allowed &= valid[:, None, :]
            allowed |= ~valid[:, :, None] & eye
            masks[value] = hidden.new_zeros((batch, 1, length, length)).masked_fill(
                ~allowed[:, None], torch.finfo(hidden.dtype).min
            )
        positional = self.rotary_emb(hidden, position_ids)
        bank, partial = (hidden,), None
        for index, layer in enumerate(self.layers):
            read = (
                hidden
                if str(index) not in self.attnres_routers
                else self.attnres_routers[str(index)](hidden, bank if partial is None else (*bank, partial))
            )
            mask = masks.get(bidirectional and index in selected)
            if self.training and self.gradient_checkpointing:
                hidden, mixed, ffn = self._gradient_checkpointing_func(
                    self._run_layer, layer, hidden, positional, mask, read, valid
                )
            else:
                hidden, mixed, ffn = self._run_layer(layer, hidden, positional, mask, read, valid)
            hidden, mixed, ffn = hidden * keep, mixed * keep, ffn * keep
            if self.attnres_routers:
                partial = mixed + ffn if partial is None else partial + mixed + ffn
                if layer.block_type == "full_attention":
                    bank, partial = (*bank, partial), None
        return self.norm(hidden) * keep


@auto_docstring
class GS1PreTrainedModel(PreTrainedModel):
    config: GS1Config
    base_model_prefix = "language_model"
    supports_gradient_checkpointing = True
    _no_split_modules = ["GS1DecoderLayer"]
    _supports_flash_attn = True
    _supports_sdpa = True
    _keys_to_ignore_on_load_unexpected = [r"^mtp.*"]
    _can_record_outputs = {"hidden_states": GS1DecoderLayer, "attentions": "self_attn"}
    _is_stateful = True

    def _init_weights(self, module):
        super()._init_weights(module)
        if isinstance(module, nn.LayerNorm):
            init.ones_(module.weight)
            if module.bias is not None:
                init.zeros_(module.bias)
        elif isinstance(module, FADepthRouter):
            init.zeros_(module.query)


GS1_TEMPLATE = r"""{%- macro text(x) -%}
{%- set value = x if x is string else x | tojson(ensure_ascii=false, separators=(',', ':'), sort_keys=true) -%}
{{- value | replace('&', '&amp;') | replace('<', '&lt;') | replace('>', '&gt;') -}}
{%- endmacro -%}
{{- '<|im_start|>user\n<state>\n' -}}
{%- set has_images = state is sequence and state is not string and state is not mapping
    and state | selectattr('type', 'defined') | selectattr('type', 'equalto', 'image') | list -%}
{%- if has_images -%}
    {%- for part in state -%}
        {%- if part.type == 'text' -%}{{- text(part.text) -}}
        {%- elif part.type == 'image' -%}{{- '<|vision_start|><|image_pad|><|vision_end|>' -}}
        {%- else -%}{{- raise_exception('Unsupported GS1 state item') -}}{%- endif -%}
    {%- endfor -%}
{%- else -%}{{- text(state) -}}{%- endif -%}
{{- '\n</state>\n<question>\n' ~ text(question.instructions if question.instructions is not none else '') ~ '\n</question>' -}}
{%- for option in question.options -%}
    {{- '\n<option>\n' -}}
    {%- set description = question.descriptions[loop.index0] -%}
    {%- if question.type == 'choice' -%}
        {{- text(option) ~ ': ' ~ text(description if description is not none else option) -}}
    {%- elif question.type == 'noul' and description is none -%}
        {{- "The proposition is " ~ option ~ " under the question's stated semantics." -}}
    {%- else -%}
        {{- text(description) -}}
    {%- endif -%}
    {{- '\n</option>' -}}
{%- endfor -%}
{{- '<|im_end|>\n<|im_start|>assistant\n<think>\n\n</think>\n\n<|decide|><|mark|>' -}}
"""


@auto_docstring(checkpoint="bigai/GS1-9B")
class GS1ForDecision(decision.DecisionMixin, GS1PreTrainedModel):
    accepts_loss_kwargs = False

    def __init__(self, config: GS1Config):
        super().__init__(config)
        self._newline_token_ids = ()
        self.language_model = GS1TextModel(config)
        self.visual = AutoModel.from_config(config.vision_config)
        self.decision_head = GS1DecisionHead(config)
        if config.calibration["mode"] == "scalar_temperature":
            self.calibration_beta = nn.Parameter(torch.zeros(()))
        self.post_init()

    def get_input_embeddings(self):
        return self.language_model.embed_tokens

    def set_input_embeddings(self, value):
        self.language_model.embed_tokens = value

    def _decision_rows(self, input_ids, attention_mask):
        names = ("<state>", "</state>", "<question>", "</question>", "<option>", "</option>", "<|decide|>")
        try:
            marker_ids = [self.config.structural_token_ids[name] for name in names]
        except (TypeError, KeyError) as error:
            raise ValueError("GS1 config must define all seven structural token IDs") from error
        metadata, role_rows = [], []
        newline = self._newline_token_ids
        for row, ids in enumerate(input_ids):
            begin = int((~attention_mask[row].bool()).sum())
            values = ids[begin:]

            def find(token):
                return torch.where(values == token)[0].tolist()

            state_starts, state_ends = find(marker_ids[0]), find(marker_ids[1])
            question_starts, question_ends = find(marker_ids[2]), find(marker_ids[3])
            option_starts, option_ends = find(marker_ids[4]), find(marker_ids[5])
            decisions = find(marker_ids[6])
            if not (
                len(state_starts)
                == len(state_ends)
                == len(question_starts)
                == len(question_ends)
                == len(decisions)
                == 1
            ):
                raise ValueError("A GS1 prompt needs one state, question, and decision marker")
            if not option_starts or len(option_starts) != len(option_ends):
                raise ValueError("GS1 prompt candidate markers are incomplete")
            q0, q1, decision = question_starts[0], question_ends[0], decisions[0]
            markers = [state_starts[0], state_ends[0], q0, q1]
            markers.extend(pos for pair in zip(option_starts, option_ends, strict=True) for pos in pair)
            markers.append(decision)
            if any(left >= right for left, right in zip(markers, markers[1:])):
                raise ValueError("GS1 prompt markers are out of order")
            roles = torch.full_like(values, -1)
            roles[:q0], roles[q0 : option_starts[0]], roles[option_starts[0] : decision], roles[decision] = 0, 1, 2, 3

            def span(start, end):
                start += 1
                if newline and tuple(values[start : start + len(newline)].tolist()) == newline:
                    start += len(newline)
                if newline and tuple(values[end - len(newline) : end].tolist()) == newline:
                    end -= len(newline)
                return (end, end + 1) if start >= end else (start, end)

            metadata.append(
                (
                    begin,
                    state_starts[0],
                    q0,
                    q1,
                    decision,
                    span(q0, q1),
                    option_starts,
                    option_ends,
                    [span(a, b) for a, b in zip(option_starts, option_ends, strict=True)],
                )
            )
            role_rows.append(F.pad(roles, (begin, 0), value=-1))
        return metadata, torch.stack(role_rows)

    @staticmethod
    def _pool_span(sequence, start, end, span):
        return torch.stack((sequence[start], sequence[span[0] : span[1]].mean(0), sequence[end])).mean(0)

    def _vision_positions(self, input_ids, token_types, image_grid_thw):
        positions = torch.zeros(3, *input_ids.shape, device=input_ids.device, dtype=torch.long)
        grids = iter(image_grid_thw)
        merge = self.config.vision_config.spatial_merge_size
        for row in range(input_ids.shape[0]):
            begin = offset = 0
            for kind, group in groupby(token_types[row].tolist()):
                end = begin + sum(1 for _ in group)
                if kind == 0:
                    part = torch.arange(end - begin, device=input_ids.device)[None].expand(3, -1) + offset
                    offset += end - begin
                else:
                    t, h, w = map(int, next(grids))
                    h, w = h // merge, w // merge
                    part = torch.stack(
                        (
                            torch.full((t * h * w,), offset, device=input_ids.device),
                            torch.arange(offset, offset + h, device=input_ids.device).repeat_interleave(w * t),
                            torch.arange(offset, offset + w, device=input_ids.device).repeat(h * t),
                        )
                    )
                    offset += max(h, w)
                positions[:, row, begin:end] = part
                begin = end
        return positions

    @can_return_tuple
    @auto_docstring
    def forward(
        self,
        input_ids: torch.LongTensor,
        attention_mask: torch.Tensor | None = None,
        marks: torch.LongTensor | None = None,
        num_options: torch.LongTensor | None = None,
        question_type_ids: torch.LongTensor | None = None,
        labels: torch.Tensor | None = None,
        loss_weights: torch.Tensor | None = None,
        pixel_values: torch.Tensor | None = None,
        image_grid_thw: torch.LongTensor | None = None,
        mm_token_type_ids: torch.LongTensor | None = None,
        **kwargs,
    ) -> GS1DecisionOutput:
        r"""
        Args:
            marks (`torch.LongTensor`, *optional*): Decision-marker positions produced by the decision input formatter.
            num_options (`torch.LongTensor`, *optional*): Candidate count for each logical question.
            question_type_ids (`torch.LongTensor`, *optional*): Encoded decision question types.
            labels (`torch.FloatTensor`, *optional*): Flat concatenation of soft target distributions.
            loss_weights (`torch.FloatTensor`, *optional*): Per-question objective weights.
            pixel_values (`torch.FloatTensor`, *optional*): Processed image patches for visual states.
            image_grid_thw (`torch.LongTensor`, *optional*): Temporal and spatial image grid sizes.
            mm_token_type_ids (`torch.LongTensor`, *optional*): Text/image token type IDs.
        """
        if attention_mask is None:
            attention_mask = torch.ones_like(input_ids)
        metadata, roles = self._decision_rows(input_ids, attention_mask)
        hidden = self.get_input_embeddings()(input_ids)
        position_ids = (attention_mask.long().cumsum(-1) - 1).clamp_min(0)
        if pixel_values is not None:
            features = self.visual(
                pixel_values.to(self.visual.dtype), grid_thw=image_grid_thw, return_dict=True
            ).pooler_output.to(hidden.device, hidden.dtype)
            image_mask = (input_ids == self.config.image_token_id).unsqueeze(-1).expand_as(hidden)
            if hidden[image_mask].numel() != features.numel():
                raise ValueError("Image feature count differs from GS1 image markers")
            hidden = hidden.masked_scatter(image_mask, features)
            if mm_token_type_ids is None:
                raise ValueError("GS1 vision inputs require mm_token_type_ids")
            position_ids = self._vision_positions(input_ids, mm_token_type_ids, image_grid_thw)
        hidden = self.language_model(hidden, position_ids, roles, attention_mask)
        logits = []
        for row, (begin, state_start, q0, q1, decision_position, qspan, starts, ends, spans) in enumerate(metadata):
            sequence = hidden[row, begin:]
            question = self._pool_span(sequence, q0, q1, qspan)
            options = torch.stack(
                [
                    self._pool_span(sequence, start, end, span)
                    for start, end, span in zip(starts, ends, spans, strict=True)
                ]
            )
            logits.append(self.decision_head(sequence[state_start:q0], question, sequence[decision_position], options))
        logits = torch.cat(logits)
        loss = None
        if labels is not None:
            option_counts = torch.tensor([len(row[-1]) for row in metadata], device=logits.device)
            loss = self.loss_function(
                logits=logits,
                labels=labels,
                num_options=option_counts,
                loss_weights=loss_weights,
                brier_weight=self.config.decision_brier_weight,
                **kwargs,
            )
        return GS1DecisionOutput(loss=loss, logits=logits)

    def post_init(self):
        super().post_init()
        self.decision_config = decision.configuration_utils.DecisionConfig(
            chat_template=GS1_TEMPLATE, sanitize_control_tokens=True, noul_options=["false", "true"]
        )

    @classmethod
    def from_pretrained(cls, pretrained_model_name_or_path, *args, **kwargs):
        result = super().from_pretrained(pretrained_model_name_or_path, *args, **kwargs)
        model = result[0] if isinstance(result, tuple) else result
        from ... import AutoTokenizer

        tokenizer = AutoTokenizer.from_pretrained(
            pretrained_model_name_or_path, **decision.modeling_utils._hub_kwargs(kwargs)
        )
        model._newline_token_ids = tuple(tokenizer.encode("\n", add_special_tokens=False))
        if model.decision_config.chat_template is None:
            model.decision_config.chat_template = GS1_TEMPLATE
            model.decision_config.noul_options = ["false", "true"]
        return result


__all__ = ["GS1PreTrainedModel", "GS1ForDecision"]
